import { db } from '../firebase.ts';
import { hashPassword } from './password.ts';
import {
  DEFAULT_BUSINESS_ID,
  sanitizeStaffPermissions,
  type ThemePreference,
  type UserRole,
} from './constants.ts';

export interface StoredUser {
  id: string;
  nombre: string;
  email: string;
  loginUsername: string;
  passwordHash?: string;
  googleId?: string;
  rol: UserRole;
  permisos: string[];
  activo: boolean;
  tema?: ThemePreference;
  colaboradorId?: string | null;
  createdAt?: string;
  updatedAt?: string;
}

export interface PublicUser {
  id: string;
  nombre: string;
  email: string;
  loginUsername: string;
  rol: UserRole;
  permisos: string[];
  activo: boolean;
  hasPassword: boolean;
  hasGoogle: boolean;
  tema?: ThemePreference;
  colaboradorId?: string | null;
  createdAt?: string;
  updatedAt?: string;
}

function usersCollection(businessId: string) {
  return db.collection(`negocios/${businessId}/usuarios`);
}

function normalizeEmail(email: unknown): string {
  return String(email ?? '')
    .trim()
    .toLowerCase();
}

function normalizeLogin(login: unknown): string {
  return String(login ?? '')
    .trim()
    .toLowerCase();
}

function normalizeTheme(value: unknown): ThemePreference {
  return value === 'dark' ? 'dark' : 'light';
}

function normalizeColaboradorId(value: unknown, rol: UserRole): string | null {
  if (rol !== 'staff') return null;
  const id = String(value ?? '').trim();
  return id || null;
}

function mapStoredUser(id: string, data: Record<string, unknown>): StoredUser {
  const rol: UserRole =
    data.rol === 'supervisor' || data.rol === 'admin' ? data.rol : 'staff';

  return {
    id,
    nombre: String(data.nombre ?? '').trim(),
    email: normalizeEmail(data.email),
    loginUsername: normalizeLogin(data.loginUsername),
    passwordHash: data.passwordHash ? String(data.passwordHash) : undefined,
    googleId: data.googleId ? String(data.googleId) : undefined,
    rol,
    permisos:
      rol === 'staff' || rol === 'admin' ? sanitizeStaffPermissions(data.permisos) : [],
    activo: data.activo !== false,
    tema: normalizeTheme(data.tema),
    colaboradorId: normalizeColaboradorId(data.colaboradorId, rol),
    createdAt: data.createdAt,
    updatedAt: data.updatedAt,
  };
}

export function toPublicUser(user: StoredUser): PublicUser {
  return {
    id: user.id,
    nombre: user.nombre,
    email: user.email,
    loginUsername: user.loginUsername,
    rol: user.rol,
    permisos: user.permisos,
    activo: user.activo,
    hasPassword: !!user.passwordHash,
    hasGoogle: !!user.googleId,
    tema: user.tema ?? 'light',
    colaboradorId: user.colaboradorId ?? null,
    createdAt: user.createdAt,
    updatedAt: user.updatedAt,
  };
}

export async function ensureDefaultSupervisor(
  businessId = DEFAULT_BUSINESS_ID
): Promise<void> {
  const col = usersCollection(businessId);
  const snapshot = await col.get();
  if (!snapshot.empty) return;

  const passwordHash = await hashPassword('admin');
  await col.add({
    nombre: 'Supervisor',
    loginUsername: 'admin',
    email: '',
    passwordHash,
    rol: 'supervisor',
    permisos: [],
    activo: true,
    createdAt: new Date().toISOString(),
  });
}

export async function listUsers(businessId: string): Promise<PublicUser[]> {
  await ensureDefaultSupervisor(businessId);
  const snapshot = await usersCollection(businessId).get();
  return snapshot.docs
    .map((doc) => toPublicUser(mapStoredUser(doc.id, doc.data())))
    .sort((a, b) => a.nombre.localeCompare(b.nombre, 'es'));
}

export async function listUsersPage(
  businessId: string,
  limit: number,
  cursor?: string
): Promise<{ items: PublicUser[]; nextCursor: string | null; hasMore: boolean }> {
  await ensureDefaultSupervisor(businessId);

  let query = usersCollection(businessId).orderBy('nombre').limit(limit + 1);

  if (cursor) {
    const cursorSnap = await usersCollection(businessId).doc(cursor).get();
    if (cursorSnap.exists) {
      query = query.startAfter(cursorSnap);
    }
  }

  const snapshot = await query.get();
  const hasMore = snapshot.docs.length > limit;
  const docs = hasMore ? snapshot.docs.slice(0, limit) : snapshot.docs;
  const items = docs.map((doc) => toPublicUser(mapStoredUser(doc.id, doc.data() ?? {})));
  const nextCursor = hasMore && docs.length > 0 ? docs[docs.length - 1].id : null;
  return { items, nextCursor, hasMore };
}

export async function getStoredUser(
  businessId: string,
  userId: string
): Promise<StoredUser | null> {
  const doc = await usersCollection(businessId).doc(userId).get();
  if (!doc.exists) return null;
  return mapStoredUser(doc.id, doc.data()!);
}

export async function findUserByLoginOrEmail(
  businessId: string,
  login: string
): Promise<StoredUser | null> {
  const normalized = normalizeLogin(login);
  if (!normalized) return null;

  const col = usersCollection(businessId);
  const byLogin = await col.where('loginUsername', '==', normalized).limit(1).get();
  if (!byLogin.empty) {
    return mapStoredUser(byLogin.docs[0].id, byLogin.docs[0].data());
  }

  if (normalized.includes('@')) {
    const byEmail = await col.where('email', '==', normalized).limit(1).get();
    if (!byEmail.empty) {
      return mapStoredUser(byEmail.docs[0].id, byEmail.docs[0].data());
    }
  }

  return null;
}

export async function findUserByEmail(
  businessId: string,
  email: string
): Promise<StoredUser | null> {
  const normalized = normalizeEmail(email);
  if (!normalized) return null;

  const snapshot = await usersCollection(businessId)
    .where('email', '==', normalized)
    .limit(1)
    .get();
  if (!snapshot.empty) {
    return mapStoredUser(snapshot.docs[0].id, snapshot.docs[0].data());
  }

  // Compat: emails guardados antes de normalizar a minúsculas en Firestore.
  const all = await usersCollection(businessId).get();
  for (const doc of all.docs) {
    const user = mapStoredUser(doc.id, doc.data());
    if (user.email === normalized) return user;
  }

  return null;
}

export async function linkGoogleId(
  businessId: string,
  userId: string,
  googleId: string
): Promise<void> {
  await usersCollection(businessId).doc(userId).update({
    googleId,
    updatedAt: new Date().toISOString(),
  });
}

export async function assertColaboradorLinkAvailable(
  businessId: string,
  colaboradorId: string | null | undefined,
  excludeUserId?: string
): Promise<void> {
  const id = String(colaboradorId ?? '').trim();
  if (!id) return;

  const snapshot = await usersCollection(businessId).where('colaboradorId', '==', id).get();
  for (const doc of snapshot.docs) {
    if (excludeUserId && doc.id === excludeUserId) continue;
    const data = doc.data() as Record<string, unknown>;
    if (data.rol !== 'staff') continue;
    if (data.activo === false) continue;
    throw new Error('COLABORADOR_ALREADY_LINKED');
  }
}

export async function assertUserLoginAndEmailAvailable(
  businessId: string,
  params: { loginUsername: string; email?: string; excludeUserId: string }
): Promise<void> {
  const snapshot = await usersCollection(businessId).get();
  for (const doc of snapshot.docs) {
    if (doc.id === params.excludeUserId) continue;
    const user = mapStoredUser(doc.id, doc.data());
    if (user.loginUsername === params.loginUsername) {
      throw new Error('LOGIN_USERNAME_TAKEN');
    }
    if (params.email && user.email && user.email === params.email) {
      throw new Error('EMAIL_TAKEN');
    }
  }
}

export async function updateUserProfile(
  businessId: string,
  userId: string,
  payload: { nombre: string; email: string; loginUsername: string }
): Promise<StoredUser> {
  const nombre = String(payload.nombre ?? '').trim();
  const email = normalizeEmail(payload.email);
  const loginUsername = normalizeLogin(payload.loginUsername);

  if (!nombre) {
    throw new Error('NAME_REQUIRED');
  }
  if (!loginUsername) {
    throw new Error('LOGIN_REQUIRED');
  }

  await assertUserLoginAndEmailAvailable(businessId, {
    loginUsername,
    email: email || undefined,
    excludeUserId: userId,
  });

  await usersCollection(businessId).doc(userId).update({
    nombre,
    email,
    loginUsername,
    updatedAt: new Date().toISOString(),
  });

  const updated = await getStoredUser(businessId, userId);
  if (!updated) {
    throw new Error('USER_NOT_FOUND');
  }
  return updated;
}

export async function countActiveSupervisors(businessId: string): Promise<number> {
  const snapshot = await usersCollection(businessId)
    .where('rol', '==', 'supervisor')
    .where('activo', '==', true)
    .get();
  return snapshot.size;
}

export async function countActiveAdministrators(businessId: string): Promise<number> {
  const { administradoresActivos } = await getActiveUserCounts(businessId);
  return administradoresActivos;
}

export async function countActiveOperators(businessId: string): Promise<number> {
  const { operadoresActivos } = await getActiveUserCounts(businessId);
  return operadoresActivos;
}

export async function countActiveUsers(businessId: string): Promise<number> {
  const { usuariosActivos } = await getActiveUserCounts(businessId);
  return usuariosActivos;
}

export async function getActiveUserCounts(businessId: string): Promise<{
  administradoresActivos: number;
  operadoresActivos: number;
  usuariosActivos: number;
}> {
  const snapshot = await usersCollection(businessId).where('activo', '==', true).get();
  let administradoresActivos = 0;
  let operadoresActivos = 0;

  for (const doc of snapshot.docs) {
    const rol = doc.data().rol;
    if (rol === 'supervisor' || rol === 'admin') administradoresActivos += 1;
    if (rol === 'staff') operadoresActivos += 1;
  }

  return {
    administradoresActivos,
    operadoresActivos,
    usuariosActivos: snapshot.size,
  };
}
