router.post('/:businessId/:orderId/finalize', async (req, res) => {
  try {
    const paymentAllowed = assertStaffOrderPaymentAllowed(req as AuthenticatedRequest);
    if (!paymentAllowed.ok) {
      return res.status(paymentAllowed.status).json({ error: paymentAllowed.error });
    }
    const { businessId, orderId } = req.params;
    const modeRaw = String(req.body.mode ?? 'full').toLowerCase();
    const mode =
      modeRaw === 'partial' || modeRaw === 'pending' || modeRaw === 'full'
        ? modeRaw
        : 'full';
    const { finalizeOrder } = await import('../domain/orders/orders-application-service.ts');
    const result = await finalizeOrder({
      businessId,
      orderId,
      source: 'erp',
      mode,
      amountPaid: req.body.amountPaid != null ? Number(req.body.amountPaid) : undefined,
      paymentMethod: req.body.paymentMethod
        ? String(req.body.paymentMethod).trim().toLowerCase()
        : undefined,
    });
    await logActivityFromRequest(req as AuthenticatedRequest, businessId, {
      module: 'orders',
      action: 'update',
      entityType: 'pedido',
      entityId: orderId,
      summary: result.alreadyFinalized
        ? `Pedido ya estaba finalizado`
        : `Finalizó el pedido (${mode})`,
    });
    void import('../automation/attention-sync.ts')
      .then((m) => m.syncAttentionNotices(businessId))
      .catch(() => undefined);
    res.json(result);
  } catch (error) {
    const msg = error instanceof Error ? error.message : '';
    if (msg === 'ORDER_NOT_FOUND') return res.status(404).json({ error: 'Pedido no encontrado.' });
    if (msg === 'ORDER_CANCELLED') return res.status(400).json({ error: 'Pedido cancelado.' });
    if (msg === 'ORDER_NOT_READY') return res.status(400).json({ error: 'Confirmá el pedido antes de finalizar.' });
    if (msg === 'AMOUNT_REQUIRED') return res.status(400).json({ error: 'Indicá el monto cobrado.' });
    if (msg === 'AMOUNT_EXCEEDS_BALANCE') {
      return res.status(400).json({ error: 'El monto supera el saldo del pedido.' });
    }
    console.error('Error finalizing order:', error);
    res.status(500).json({ error: 'No se pudo finalizar el pedido.' });
  }
});

router.post('/:businessId/:orderId/pagos', async (req, res) => {
  try {
    const paymentAllowed = assertStaffOrderPaymentAllowed(req as AuthenticatedRequest);
    if (!paymentAllowed.ok) {
      return res.status(paymentAllowed.status).json({ error: paymentAllowed.error });
    }

    const { businessId, orderId } = req.params;
    const monto = Number(req.body.monto) || 0;
    const notas = String(req.body.notas ?? '').trim();

    if (monto <= 0) {
      return res.status(400).json({ error: 'El monto debe ser mayor a cero.' });
    }

    const orderRef = db.collection(`negocios/${businessId}/pedidos`).doc(orderId);
    const orderSnap = await orderRef.get();
    if (!orderSnap.exists) return res.status(404).json({ error: 'Order not found' });

    const order = orderSnap.data() as OrderRecord;
    if (isCancelledStatus(order.estado)) {
      return res.status(403).json({ error: 'No se pueden registrar pagos en un pedido cancelado.' });
    }
    if (!orderAllowsPayments(order)) {
      return res.status(400).json({ error: 'Confirmá el pedido antes de registrar pagos.' });
    }

    const pagosBase = normalizePagos(order);
    const balance = resolveOrderBalance({
      total: order.total,
      senia: order.senia,
      totalPagado: order.totalPagado,
      pagos: pagosBase,
      seniaBloqueada: order.seniaBloqueada,
      movimientoSeniaId: order.movimientoSeniaId,
      items: order.items,
    });
    const total = balance.total;
    const saldoPedido = balance.saldo;

    const storedTotal = Number(order.total) || 0;
    const storedSaldo = Number(order.saldo) || 0;
    if (
      Math.abs(total - storedTotal) > 0.009 ||
      Math.abs(saldoPedido - storedSaldo) > 0.009
    ) {
      await orderRef.update({
        total,
        saldo: saldoPedido,
        updatedAt: new Date().toISOString(),
      });
    }

    if (saldoPedido <= 0) {
      return res.status(403).json({ error: 'Este pedido no tiene saldo pendiente.' });
    }

    if (monto > saldoPedido) {
      return res.status(400).json({
        error: `El monto supera el saldo pendiente ($${saldoPedido}).`,
        saldoPedido,
      });
    }

    const orderLabel = resolveOrderLabel(order);
    const timestamp = Date.now();
    const movimientoCajaId = await createCashIncome(businessId, {
      monto,
      concepto: `Cuota pedido #${orderLabel}`,
      origenId: orderId,
      origenTipo: 'pedido_cuota',
      clienteId: order.clienteId,
      pedidoId: orderId,
      numeroPedido: order.numeroPedido,
      numeroPedidoLabel: order.numeroPedidoLabel ?? orderLabel,
    });

    const nuevosPagos: OrderPayment[] = [
      {
        id: `pago_${timestamp}`,
        tipo: 'cuota',
        monto,
        fecha: new Date().toISOString(),
        movimientoCajaId,
        notas: notas || undefined,
      },
    ];

    const pagos = [...pagosBase, ...nuevosPagos].map(sanitizePagoForFirestore);
    const totalPagado = sumPagosHaciaTotal(
      pagos.map((pago) => ({
        tipo: String(pago.tipo ?? 'pago'),
        monto: Number(pago.monto) || 0,
      }))
    );
    const saldo = resolveOrderBalance({
      total,
      senia: order.senia,
      totalPagado,
      pagos,
      seniaBloqueada: true,
      movimientoSeniaId: order.movimientoSeniaId,
      items: order.items,
    }).saldo;

    await orderRef.update({
      pagos,
      total,
      totalPagado,
      saldo,
      seniaBloqueada: true,
      updatedAt: new Date().toISOString(),
    });

    await syncOrderLinkedVentaSaldo(businessId, order, saldo, total);

    await logActivityFromRequest(req as AuthenticatedRequest, businessId, {
      module: 'orders',
      action: 'payment',
      entityType: 'pedido',
      entityId: orderId,
      entityLabel: orderLabel,
      summary: `Registró pago de $${monto} en pedido #${orderLabel}`,
    });

    res.status(201).json({
      id: orderId,
      pago: nuevosPagos[0],
      pagos: nuevosPagos,
      allPagos: pagos,
      totalPagado,
      saldo,
    });
  } catch (error) {
    console.error('Error registering payment:', error);
    const message = error instanceof Error ? error.message : 'Error registering payment';
    res.status(500).json({ error: message });
  }
});

router.delete('/:businessId/:orderId/pagos/:pagoId', async (req, res) => {
  try {
    const { businessId, orderId, pagoId } = req.params;
    const orderRef = db.collection(`negocios/${businessId}/pedidos`).doc(orderId);
    const orderSnap = await orderRef.get();
    if (!orderSnap.exists) return res.status(404).json({ error: 'Order not found' });

    const order = orderSnap.data() as OrderRecord;
    const pago = findStoredOrderPayment(order, pagoId);
    if (!pago) return res.status(404).json({ error: 'Pago no encontrado.' });

    const storedPagos = [...(order.pagos ?? [])].filter(
      (row) => row && typeof row === 'object'
    ) as OrderPayment[];
    const pagosAfterRemoval = storedPagos.filter((row) => row.id !== pago.id);
    const removalError = validateOrderPaymentRemoval(order, pago, pagosAfterRemoval);
    if (removalError) {
      return res.status(403).json({ error: removalError });
    }

    if (pago.movimientoCajaId) {
      const movementRef = db
        .collection(`negocios/${businessId}/movimientos_caja`)
        .doc(pago.movimientoCajaId);
      const movementSnap = await movementRef.get();
      if (movementSnap.exists) {
        await movementRef.delete();
      }
    }

    const balance = resolveOrderBalance({
      total: order.total,
      senia: order.senia,
      pagos: pagosAfterRemoval,
      seniaBloqueada: order.seniaBloqueada,
      movimientoSeniaId:
        pago.tipo === 'seña' || pago.movimientoCajaId === order.movimientoSeniaId
          ? null
          : order.movimientoSeniaId,
      items: order.items,
    });

    const updatePayload: Record<string, unknown> = {
      pagos: pagosAfterRemoval.map(sanitizePagoForFirestore),
      total: balance.total,
      totalPagado: balance.pagado,
      saldo: balance.saldo,
      updatedAt: new Date().toISOString(),
    };

    if (pago.tipo === 'seña' || pago.movimientoCajaId === order.movimientoSeniaId) {
      updatePayload.movimientoSeniaId = null;
      updatePayload.seniaBloqueada = false;
    }

    await orderRef.update(updatePayload);
    await syncOrderLinkedVentaSaldo(businessId, order, balance.saldo, balance.total);

    const orderLabel = resolveOrderLabel(order);
    await logActivityFromRequest(req as AuthenticatedRequest, businessId, {
      module: 'orders',
      action: 'delete',
      entityType: 'pedido',
      entityId: orderId,
      entityLabel: orderLabel,
      summary: `Anuló pago de $${Number(pago.monto) || 0} en pedido #${orderLabel}`,
    });

    res.json({
      id: orderId,
      pagos: pagosAfterRemoval,
      totalPagado: balance.pagado,
      saldo: balance.saldo,
      seniaBloqueada: updatePayload.seniaBloqueada ?? order.seniaBloqueada,
      movimientoSeniaId:
        updatePayload.movimientoSeniaId !== undefined
          ? updatePayload.movimientoSeniaId
          : order.movimientoSeniaId,
    });
  } catch (error) {
    console.error('Error removing order payment:', error);
    const message = error instanceof Error ? error.message : 'Error removing payment';
    res.status(500).json({ error: message });
  }
});

router.post('/:businessId/:orderId/fotos', async (req, res) => {
  try {
    const { businessId, orderId } = req.params;
    if (!(await assertOrderPhotosModule(businessId, res))) return;
    const pedidosConfig = await loadOrderPedidosConfig(businessId);
    if (!pedidosConfig.fotosReferenciaHabilitadas) {
      return res.status(403).json({ error: 'Las fotos de referencia están desactivadas en configuración.' });
    }

    const orderRef = db.collection(`negocios/${businessId}/pedidos`).doc(orderId);
    const orderSnap = await orderRef.get();
    if (!orderSnap.exists) return res.status(404).json({ error: 'Order not found' });

    const order = orderSnap.data() as OrderRecord;
    if (isCancelledStatus(order.estado)) {
      return res.status(403).json({ error: 'No se pueden adjuntar fotos a un pedido cancelado.' });
    }

    const existing = normalizeOrderPhotos(order.fotos);
    if (existing.length >= MAX_ORDER_PHOTOS) {
      return res.status(400).json({
        error: `El pedido ya tiene el máximo de ${MAX_ORDER_PHOTOS} fotos.`,
      });
    }

    const { buffer, contentType, name } = parsePhotoUpload(req.body);
    const photo = await uploadOrderPhoto(businessId, orderId, buffer, contentType, name);
    const fotos = [...existing, photo];

    await orderRef.update({
      fotos,
      updatedAt: new Date().toISOString(),
    });

    const [withUrl] = await resolveOrderPhotoUrls([photo]);
    const orderLabel = resolveOrderLabel(order);

    await logActivityFromRequest(req as AuthenticatedRequest, businessId, {
      module: 'orders',
      action: 'update',
      entityType: 'pedido',
      entityId: orderId,
      entityLabel: orderLabel,
      summary: `Adjuntó una foto de referencia al pedido #${orderLabel}`,
    });

    res.status(201).json({ id: orderId, foto: withUrl, fotos: await resolveOrderPhotoUrls(fotos) });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Error uploading photo';
    const status = message.includes('Formato') || message.includes('Falta') || message.includes('supera')
      ? 400
      : 500;
    if (status === 500) console.error('Error uploading order photo:', error);
    res.status(status).json({ error: message });
  }
});

router.delete('/:businessId/:orderId/fotos/:photoId', async (req, res) => {
  try {
    const { businessId, orderId, photoId } = req.params;
    if (!(await assertOrderPhotosModule(businessId, res))) return;
    const orderRef = db.collection(`negocios/${businessId}/pedidos`).doc(orderId);
    const orderSnap = await orderRef.get();
    if (!orderSnap.exists) return res.status(404).json({ error: 'Order not found' });

    const order = orderSnap.data() as OrderRecord;
    if (isCancelledStatus(order.estado)) {
      return res.status(403).json({ error: 'No se pueden quitar fotos de un pedido cancelado.' });
    }

    const existing = normalizeOrderPhotos(order.fotos);
    const target = existing.find((photo) => photo.id === photoId);
    if (!target) {
      return res.status(404).json({ error: 'Foto no encontrada.' });
    }

    await deleteOrderPhotoFile(target.storagePath);
    const fotos = existing.filter((photo) => photo.id !== photoId);
    await orderRef.update({
      fotos,
      updatedAt: new Date().toISOString(),
    });

    const orderLabel = resolveOrderLabel(order);
    await logActivityFromRequest(req as AuthenticatedRequest, businessId, {
      module: 'orders',
      action: 'update',
      entityType: 'pedido',
      entityId: orderId,
      entityLabel: orderLabel,
      summary: `Eliminó una foto de referencia del pedido #${orderLabel}`,
    });

    res.json({ id: orderId, fotos: await resolveOrderPhotoUrls(fotos) });
  } catch (error) {
    console.error('Error deleting order photo:', error);
    res.status(500).json({ error: 'Error deleting photo' });
  }
});

function assertStaffOrderPaymentAllowed(
  req: AuthenticatedRequest
): { ok: true } | { ok: false; status: number; error: string } {
  const auth = req.auth;
  if (!auth || auth.scope !== 'company') return { ok: true };

  const user = auth.user;
  if (isPrivilegedRole(user.rol)) return { ok: true };
  if (userHasPermission(user.rol, user.permisos, 'records.edit')) return { ok: true };
  if (userHasPermission(user.rol, user.permisos, 'cash.access')) return { ok: true };
  if (userHasPermission(user.rol, user.permisos, 'orders.viewSalePrice')) return { ok: true };

  return {
    ok: false,
    status: 403,
    error: 'No tenés permiso para registrar pagos en pedidos.',
  };
}

function assertStaffOrderUpdateAllowed(
  req: AuthenticatedRequest,
  patch: Record<string, unknown>
): { ok: true } | { ok: false; status: number; error: string } {
  const auth = req.auth;
  if (!auth || auth.scope !== 'company') return { ok: true };

  const user = auth.user;
  if (isPrivilegedRole(user.rol)) return { ok: true };

  if (userHasPermission(user.rol, user.permisos, 'records.edit')) {
    return { ok: true };
  }

  if (!userHasPermission(user.rol, user.permisos, 'orders.changeStatus')) {
    return {
      ok: false,
      status: 403,
      error: 'No tenés permiso para modificar pedidos.',
    };
  }

  const allowedKeys = new Set(['estado', 'descuentoFisicoAlcance', 'entregaModo']);
  const disallowed = Object.keys(patch).filter(
    (key) => patch[key] !== undefined && !allowedKeys.has(key)
  );
  if (disallowed.length > 0) {
    return {
      ok: false,
      status: 403,
      error: 'Solo podés cambiar el estado del pedido.',
    };
  }

  return { ok: true };
}

router.patch('/:businessId/:orderId', async (req, res) => {
  try {
    const { businessId, orderId } = req.params;
    const incomingSenia = req.body.senia;
    const incomingFecha = req.body.fecha ?? req.body.createdAt;
    const { id, createdAt, senia, movimientoSeniaId, pagos, totalPagado, seniaBloqueada, ...orderData } =
      req.body;

    const orderRef = db.collection(`negocios/${businessId}/pedidos`).doc(orderId);
    const existingDoc = await orderRef.get();
    if (!existingDoc.exists) return res.status(404).json({ error: 'Order not found' });

    const existingOrder = existingDoc.data() as OrderRecord;
    const permissionCheck = assertStaffOrderUpdateAllowed(
      req as AuthenticatedRequest,
      orderData as Record<string, unknown>
    );
    if (!permissionCheck.ok) {
      return res.status(permissionCheck.status).json({ error: permissionCheck.error });
    }
    if (
      incomingFecha !== undefined &&
      incomingFecha !== null &&
      String(incomingFecha).trim()
    ) {
      orderData.createdAt = normalizeTransactionDateToIso(
        incomingFecha,
        new Date(String(existingOrder.createdAt ?? Date.now()))
      );
    }
    if (isCancelledStatus(existingOrder.estado)) {
      return res.status(403).json({ error: 'No se puede modificar un pedido cancelado.' });
    }
    if (isEntregadoTotalStatus(existingOrder.estado, existingOrder)) {
      const hasIncomingFecha =
        incomingFecha !== undefined &&
        incomingFecha !== null &&
        String(incomingFecha).trim();
      const patchKeys = Object.keys(orderData).filter(
        (key) => orderData[key] !== undefined && orderData[key] !== null
      );
      const descriptionOnly =
        !hasIncomingFecha &&
        patchKeys.length === 1 &&
        patchKeys[0] === 'descripcion';

      if (!descriptionOnly) {
        return res.status(403).json({
          error:
            'Este pedido fue entregado total. Solo podés actualizar la descripción del trabajo.',
        });
      }

      await orderRef.update({
        descripcion: String(orderData.descripcion ?? '').trim(),
        updatedAt: new Date().toISOString(),
      });

      const orderLabel = resolveOrderLabel(existingOrder);
      await logActivityFromRequest(req as AuthenticatedRequest, businessId, {
        module: 'orders',
        action: 'update',
        entityType: 'pedido',
        entityId: orderId,
        entityLabel: orderLabel,
        summary: `Actualizó la descripción del pedido #${orderLabel}`,
      });

      return res.json({
        id: orderId,
        estado: existingOrder.estado,
        pagos: existingOrder.pagos ?? [],
        totalPagado: existingOrder.totalPagado,
        saldo: existingOrder.saldo,
        entregadoAt: existingOrder.entregadoAt,
        ventaId: existingOrder.ventaId,
        locked: true,
        items: existingOrder.items,
        estadoStock: existingOrder.estadoStock,
        stockPreparado: existingOrder.stockPreparado,
        stockDescontado: existingOrder.stockDescontado,
      });
    }

    const mergedEstado = orderData.estado ?? existingOrder.estado;
    const mergedOrder: OrderRecord = {
      ...existingOrder,
      ...orderData,
      estado: mergedEstado,
      senia: existingOrder.senia,
      pagos: existingOrder.pagos,
      totalPagado: existingOrder.totalPagado,
      seniaBloqueada: existingOrder.seniaBloqueada,
      movimientoSeniaId: existingOrder.movimientoSeniaId,
      stockDescontado: existingOrder.stockDescontado,
    };

    if (isDraftStatus(mergedEstado) && !existingOrder.seniaBloqueada && incomingSenia !== undefined) {
      orderData.senia = Number(incomingSenia) || 0;
      mergedOrder.senia = orderData.senia;
    }

    let orderNumberPatch: Partial<OrderRecord> = {};
    if (!isDraftStatus(mergedEstado) && !existingOrder.numeroPedido) {
      const allocated = await allocateOrderNumber(businessId);
      orderNumberPatch = {
        numeroPedido: allocated.numero,
        numeroPedidoLabel: allocated.label,
      };
      Object.assign(mergedOrder, orderNumberPatch);
      orderData.numeroPedido = allocated.numero;
      orderData.numeroPedidoLabel = allocated.label;
    }

    let seniaPatch: Partial<OrderRecord> = {};
    if (
      !existingOrder.seniaBloqueada &&
      Number(incomingSenia) > 0 &&
      !isDraftStatus(mergedEstado)
    ) {
      seniaPatch = await registerInitialSenia(businessId, orderId, {
        ...mergedOrder,
        senia: Number(incomingSenia),
        total: orderData.total ?? existingOrder.total,
        clienteId: orderData.clienteId ?? existingOrder.clienteId,
      });
      Object.assign(mergedOrder, seniaPatch);
    }

    if (orderData.total !== undefined) {
      const total = Number(orderData.total) || 0;
      const pagado = sumPagosHaciaTotal(normalizePagos(mergedOrder));
      mergedOrder.saldo = Math.max(0, total - pagado);
      orderData.saldo = mergedOrder.saldo;
    } else if (!existingOrder.seniaBloqueada && (mergedOrder.pagos?.length ?? 0) === 0) {
      const total = Number(orderData.total ?? existingOrder.total) || 0;
      orderData.saldo = total;
      mergedOrder.saldo = total;
      orderData.totalPagado = 0;
      mergedOrder.totalPagado = 0;
    } else if (isDraftStatus(mergedEstado) && !existingOrder.seniaBloqueada) {
      orderData.saldo = Number(orderData.total ?? existingOrder.total) || 0;
      mergedOrder.saldo = orderData.saldo;
    }

    let stockDescontado = mergedOrder.stockDescontado ?? false;
    let productionStockPatch: Partial<OrderRecord> = {};
    let deferredStockSyncIds: string[] = [];

    if (orderData.items !== undefined) {
      orderData.items = mergeOrderItemsPreservingStock(
        orderData.items ?? [],
        existingOrder.items ?? []
      );
      orderData.items = await enrichOrderItemsStockControl(businessId, orderData.items);
      mergedOrder.items = orderData.items;

      if (!isDraftStatus(mergedEstado)) {
        const stockItemsChanged = !orderStockItemsEquivalent(
          existingOrder.items,
          orderData.items
        );
        if (stockItemsChanged) {
          const itemsReconcile = await reconcileOrderStockOnItemsChange(
            businessId,
            orderId,
            {
              items: existingOrder.items ?? [],
              estado: existingOrder.estado,
              stockDescontado: existingOrder.stockDescontado,
              stockPreparado: existingOrder.stockPreparado,
              numeroPedido: existingOrder.numeroPedido,
              numeroPedidoLabel: existingOrder.numeroPedidoLabel,
              clienteId: existingOrder.clienteId,
            },
            orderData.items
          );
          orderData.items = itemsReconcile.items;
          mergedOrder.items = itemsReconcile.items;
          productionStockPatch = {
            items: itemsReconcile.items,
            stockDescontado: itemsReconcile.stockDescontado,
            stockPreparado: itemsReconcile.stockPreparado,
            estadoStock: itemsReconcile.estadoStock,
          };
          stockDescontado = itemsReconcile.stockDescontado;
          deferredStockSyncIds = collectChangedStockProductIds(
            existingOrder.items,
            orderData.items
          );
        }
      }
    }

    let deliveryPatch: Partial<OrderRecord> = {};
    let deliveryEntregaConSaldo: boolean | undefined;
    let deliveryEstadoOverride: string | undefined;
    const previousEstado = resolveOrderEstado(existingOrder.estado);
    const nextEstado = resolveOrderEstado(mergedEstado);
    const pedidosConfig = await loadOrderPedidosConfig(businessId);
    const stockTrigger = pedidosConfig.estadoDescuentaStock;

    if (existingOrder.estado !== mergedEstado) {
      const transition = validateOrderEstadoTransition({
        previousEstado: existingOrder.estado,
        nextEstado: mergedEstado,
        triggerEstado: stockTrigger,
        stockDescontado,
        estados: pedidosConfig.estados,
      });

      if (!transition.allowed) {
        return res.status(400).json({ error: transition.error });
      }

      if (transition.requiresStockRestore) {
        const rollback = await restoreStockForOrderEstadoRollback(
          businessId,
          orderId,
          mergedOrder,
          mergedEstado,
          pedidosConfig.estados
        );
        productionStockPatch = {
          items: rollback.items,
          stockDescontado: false,
          estadoStock: computeOrderStockStatus(rollback.items ?? []),
        };
        Object.assign(mergedOrder, productionStockPatch);
        stockDescontado = false;
      }
    }

    const stockFullyConsumed = orderStockFullyConsumed(mergedOrder.items ?? []);
    const crossesStockTrigger =
      shouldConsumeStockOnStatusChange({
        previousEstado,
        nextEstado,
        triggerEstado: stockTrigger,
        stockDescontado,
        stockFullyConsumed,
        estados: pedidosConfig.estados,
      });
    let stockWarning: string | undefined;

    if (crossesStockTrigger) {
      const requestedScope = String(req.body?.descuentoFisicoAlcance ?? '')
        .trim()
        .toLowerCase() as OrderPhysicalStockScope;
      const scope =
        requestedScope === 'solo_reservado' || requestedScope === 'pedido_completo'
          ? requestedScope
          : resolveOrderPhysicalStockScope(pedidosConfig, nextEstado);

      const consumption = await consumeOrderStockOnStatusChange(businessId, orderId, mergedOrder, {
        pedidosConfig,
        targetEstado: nextEstado,
        scope,
      });
      productionStockPatch = {
        items: consumption.items,
        stockDescontado: consumption.stockDescontado,
        estadoStock: consumption.estadoStock,
        stockPreparado: consumption.stockPreparado ?? mergedOrder.stockPreparado,
      };
      Object.assign(mergedOrder, productionStockPatch);
      stockDescontado = consumption.stockDescontado;
      stockWarning = consumption.stockWarning;
    }

    const isDeliveryTransition = isDeliveredEstado(nextEstado) && !isDeliveredEstado(previousEstado);
    if (isDeliveryTransition) {
      const deliveryConsumption = await consumeOrderStockOnDelivery(businessId, orderId, mergedOrder);
      productionStockPatch = {
        ...productionStockPatch,
        items: deliveryConsumption.items,
        stockDescontado: deliveryConsumption.stockDescontado,
        estadoStock: deliveryConsumption.estadoStock,
        stockPreparado: deliveryConsumption.stockPreparado ?? mergedOrder.stockPreparado,
      };
      Object.assign(mergedOrder, productionStockPatch);
      stockDescontado = deliveryConsumption.stockDescontado;
      if (deliveryConsumption.stockWarning) {
        stockWarning = stockWarning
          ? `${stockWarning}\n${deliveryConsumption.stockWarning}`
          : deliveryConsumption.stockWarning;
      }
    }

    const incomingEntregaModo =
      orderData.entregaModo === 'con_saldo'
        ? 'con_saldo'
        : orderData.entregaModo === 'completa'
          ? 'completa'
          : undefined;

    if (isDeliveryTransition) {
      const modo: 'completa' | 'con_saldo' =
        incomingEntregaModo ??
        (nextEstado === 'entregado_con_saldo' ? 'con_saldo' : 'completa');

      if (modo === 'con_saldo') {
        deliveryPatch = await applyEntregaConSaldoVenta(businessId, orderId, {
          ...mergedOrder,
          total: orderData.total ?? mergedOrder.total,
          costoReal: orderData.costoReal ?? mergedOrder.costoReal,
        });
        deliveryEntregaConSaldo = true;
      } else {
        deliveryPatch = await applyEntregaCompletaPayment(businessId, orderId, {
          ...mergedOrder,
          total: orderData.total ?? mergedOrder.total,
          saldo: mergedOrder.saldo,
        });
        deliveryEntregaConSaldo = false;
      }
      deliveryEstadoOverride = 'entregado';
      Object.assign(mergedOrder, deliveryPatch);
    }

    const mergedTotal = Number(orderData.total ?? existingOrder.total) || 0;
    const mergedCostoReal = Number(orderData.costoReal ?? existingOrder.costoReal) || 0;
    const mergedEstadoLabel = String(orderData.estado ?? existingOrder.estado ?? '');
    if (Array.isArray(orderData.items)) {
      const { toFirestoreOrderItem, stripUndefinedDeep: stripDeep } = await import(
        '../whatsapp/firestore-mappers.ts'
      );
      orderData.items = (orderData.items as Record<string, unknown>[]).map((line) =>
        stripDeep(
          toFirestoreOrderItem({
            stockItemId: line.stockItemId as string | undefined,
            nombre: line.nombre as string | undefined,
            cantidad: line.cantidad as number | undefined,
            precioVenta: line.precioVenta as number | undefined,
            costoUnitario: line.costoUnitario as number | undefined,
            controlaStock: line.controlaStock as boolean | undefined,
            costosExtra: line.costosExtra as Array<{ nombre?: string; costo?: number }> | undefined,
            costoPersonalizacion: line.costoPersonalizacion as number | undefined,
            tipoLinea: line.tipoLinea as 'producto' | 'concepto' | undefined,
            mueveStock: line.mueveStock as boolean | undefined,
            precioUnitario: line.precioUnitario as number | undefined,
            subtotal: line.subtotal as number | undefined,
          })
        )
      );
    }

    const { stripUndefinedDeep, assertNoUndefinedDeep } = await import(
      '../whatsapp/firestore-mappers.ts'
    );
    const updatePayload: Record<string, unknown> = stripUndefinedDeep({
      ...orderData,
      ...orderNumberPatch,
      ...seniaPatch,
      ...productionStockPatch,
      stockDescontado,
      esDonacion: mergedTotal === 0,
      gananciaEstimada: resolveOrderGananciaForStorage(
        mergedTotal,
        mergedCostoReal,
        mergedEstadoLabel,
        deliveryPatch.gananciaEstimada ?? orderData.gananciaEstimada
      ),
      updatedAt: new Date().toISOString(),
    }) as Record<string, unknown>;

    for (const key of Object.keys(updatePayload)) {
      if (updatePayload[key] === undefined) delete updatePayload[key];
    }
    assertNoUndefinedDeep(updatePayload, 'pedido.update');

    if (deliveryPatch.pagos) {
      updatePayload.pagos = deliveryPatch.pagos.map(sanitizePagoForFirestore);
      updatePayload.totalPagado = deliveryPatch.totalPagado;
      updatePayload.saldo = deliveryPatch.saldo;
      updatePayload.seniaBloqueada = deliveryPatch.seniaBloqueada;
    }
    if (deliveryPatch.entregadoAt) {
      updatePayload.entregadoAt = deliveryPatch.entregadoAt;
    }
    if (deliveryPatch.ventaId) {
      updatePayload.ventaId = deliveryPatch.ventaId;
    }
    if (deliveryPatch.saldo !== undefined && !deliveryPatch.pagos) {
      updatePayload.saldo = deliveryPatch.saldo;
    }
    if (deliveryPatch.totalPagado !== undefined && !deliveryPatch.pagos) {
      updatePayload.totalPagado = deliveryPatch.totalPagado;
    }
    if (deliveryEstadoOverride) {
      updatePayload.estado = deliveryEstadoOverride;
    }
    if (deliveryEntregaConSaldo !== undefined) {
      updatePayload.entregaConSaldo = deliveryEntregaConSaldo;
    }

    await orderRef.update(updatePayload);

    if (isDeliveryTransition && updatePayload.saldo !== undefined) {
      await syncOrderLinkedVentaSaldo(
        businessId,
        {
          ventaId: String(updatePayload.ventaId ?? mergedOrder.ventaId ?? '') || undefined,
        },
        Number(updatePayload.saldo) || 0,
        Number(updatePayload.total ?? mergedOrder.total) || 0
      );
    }

    const orderLabel = resolveOrderLabel({
      ...existingOrder,
      ...orderNumberPatch,
      numeroPedidoLabel:
        orderNumberPatch.numeroPedidoLabel ??
        existingOrder.numeroPedidoLabel ??
        orderId,
    });

    void logActivityFromRequest(req as AuthenticatedRequest, businessId, {
      module: 'orders',
      action: 'update',
      entityType: 'pedido',
      entityId: orderId,
      entityLabel: orderLabel,
      summary: `Editó el pedido #${orderLabel}${mergedEstado ? ` · estado ${mergedEstado}` : ''}`,
    }).catch((error) => console.error('[orders] activity log failed:', error));

    const responseEstado = String(updatePayload.estado ?? mergedEstado);
    res.json({
      id: orderId,
      estado: responseEstado,
      pagos: (updatePayload.pagos as OrderPayment[] | undefined) ?? mergedOrder.pagos ?? [],
      totalPagado: updatePayload.totalPagado ?? mergedOrder.totalPagado,
      saldo: updatePayload.saldo ?? mergedOrder.saldo,
      entregadoAt: updatePayload.entregadoAt ?? mergedOrder.entregadoAt,
      ventaId: updatePayload.ventaId ?? mergedOrder.ventaId,
      ventaLabel: (deliveryPatch as { ventaLabel?: string }).ventaLabel,
      deliveryPaymentApplied: !!deliveryPatch.pagos,
      saleCreated: !!deliveryPatch.ventaId,
      locked: isEntregadoTotalStatus(responseEstado, {
        entregaConSaldo: updatePayload.entregaConSaldo as boolean | undefined,
        saldo: (updatePayload.saldo as number | undefined) ?? mergedOrder.saldo,
      }),
      entregaConSaldo: updatePayload.entregaConSaldo ?? mergedOrder.entregaConSaldo,
      items: (updatePayload.items as OrderLine[] | undefined) ?? mergedOrder.items,
      estadoStock: updatePayload.estadoStock ?? mergedOrder.estadoStock,
      stockPreparado: updatePayload.stockPreparado ?? mergedOrder.stockPreparado,
      stockDescontado: updatePayload.stockDescontado ?? stockDescontado,
      stockWarning,
    });

    if (deferredStockSyncIds.length > 0) {
      void syncPendingOrdersAfterStockChange(businessId, deferredStockSyncIds).catch((error) =>
        console.error('[orders] deferred pending-order stock sync failed:', error)
      );
    }
  } catch (error) {
    if (error instanceof StockValidationError || error instanceof OrderStockError) {
      return res.status(400).json({ error: error.message });
    }
    const message = error instanceof Error ? error.message : 'Error updating order';
    res.status(500).json({ error: message });
  }
});

