import { db } from '../firebase.ts';
import {
  defaultTrialRange,
  resolveTrialState,
  type TrialStatus,
} from '../../shared/trial-state.ts';
import {
  lifecycleToErpStatus,
  resolveSubscriptionLifecycle,
} from '../../shared/subscription-lifecycle.ts';
import type { BusinessRecord } from './business.ts';

function businessRef(businessId: string) {
  return db.collection('negocios').doc(businessId);
}

export function parseTrialStatus(value: unknown): TrialStatus | null {
  if (
    value === 'active' ||
    value === 'expired' ||
    value === 'converted' ||
    value === 'cancelled'
  ) {
    return value;
  }
  return null;
}

export function buildTrialFieldUpdates(
  payload: Record<string, unknown>,
  current?: BusinessRecord,
  options?: { trialDays?: number }
): Partial<
  Pick<BusinessRecord, 'enPrueba' | 'trialStartDate' | 'trialEndDate' | 'trialStatus'>
> {
  const next: Partial<
    Pick<BusinessRecord, 'enPrueba' | 'trialStartDate' | 'trialEndDate' | 'trialStatus'>
  > = {};

  if (payload.enPrueba !== undefined) {
    next.enPrueba = payload.enPrueba === true;
  }
  if (typeof payload.trialStartDate === 'string' && payload.trialStartDate.trim()) {
    next.trialStartDate = payload.trialStartDate.trim().slice(0, 10);
  }
  if (typeof payload.trialEndDate === 'string' && payload.trialEndDate.trim()) {
    next.trialEndDate = payload.trialEndDate.trim().slice(0, 10);
  }
  if (payload.trialStatus !== undefined) {
    next.trialStatus = parseTrialStatus(payload.trialStatus);
  }

  const willBeOnTrial =
    next.enPrueba === true || (next.enPrueba === undefined && current?.enPrueba === true);

  if (next.enPrueba === true) {
    if (!current?.trialStartDate && !next.trialStartDate) {
      const range = defaultTrialRange(new Date(), options?.trialDays);
      next.trialStartDate = range.trialStartDate;
      next.trialEndDate = range.trialEndDate;
    }
    if (!next.trialStatus) {
      next.trialStatus =
        current?.trialStatus === 'expired' || current?.trialStatus === 'cancelled'
          ? 'active'
          : (current?.trialStatus ?? 'active');
    }
  }

  if (next.enPrueba === false && next.trialStatus === undefined) {
    if (current?.trialStatus === 'active' || current?.trialStatus === 'expired') {
      next.trialStatus = 'converted';
    }
  }

  if (!willBeOnTrial && next.trialStatus === undefined && payload.trialAction === 'cancel') {
    next.trialStatus = 'cancelled';
  }

  return next;
}

export async function syncExpiredTrialStatus(
  business: BusinessRecord
): Promise<BusinessRecord> {
  const trial = resolveTrialState(business);
  let next: BusinessRecord = business;
  if (
    business.enPrueba &&
    trial.trialStatus === 'expired' &&
    business.trialStatus !== 'expired'
  ) {
    await businessRef(business.id).update({
      trialStatus: 'expired',
      updatedAt: new Date().toISOString(),
    });
    next = { ...business, trialStatus: 'expired' };
  }

  const lifecycle = resolveSubscriptionLifecycle({
    estadoSuscripcion: next.estadoSuscripcion,
    enPrueba: next.enPrueba,
    trialStatus: next.trialStatus,
    trialEndDate: next.trialEndDate,
    trialStartDate: next.trialStartDate,
    paidUntil: next.billing?.paidUntil,
    autoRenew: next.billing?.autoRenew,
    mpPreapprovalStatus: next.billing?.mpPreapprovalStatus,
    lastPaymentStatus: next.billing?.lastPaymentStatus,
  });
  const cameFromTrial =
    next.enPrueba === true ||
    next.trialStatus === 'expired' ||
    next.trialStatus === 'converted' ||
    next.source === 'self_service_trial';
  const resolvedLifecycle =
    !cameFromTrial && next.estadoSuscripcion === 'activa' && lifecycle === 'inactive'
      ? 'active'
      : lifecycle;
  const erpStatus = lifecycleToErpStatus(resolvedLifecycle);
  const shouldMarkInactive =
    resolvedLifecycle === 'inactive' && cameFromTrial && next.estadoSuscripcion === 'activa';
  const shouldMarkPastDue = resolvedLifecycle === 'past_due' && next.estadoSuscripcion !== 'vencida';
  const shouldStoreLifecycle = next.billing?.lifecycleStatus !== resolvedLifecycle;

  if (!shouldMarkInactive && !shouldMarkPastDue && !shouldStoreLifecycle) {
    return next;
  }

  const now = new Date().toISOString();
  const billingClean = Object.fromEntries(
    Object.entries(next.billing ?? {}).filter(([, value]) => value !== undefined)
  );
  const patch: Record<string, unknown> = {
    billing: {
      ...billingClean,
      lifecycleStatus: resolvedLifecycle,
      updatedAt: now,
    },
    updatedAt: now,
  };
  if (shouldMarkInactive) {
    patch.estadoSuscripcion = erpStatus;
    patch.enPrueba = false;
    patch.trialStatus = 'expired';
  } else if (shouldMarkPastDue) {
    patch.estadoSuscripcion = erpStatus;
  }
  await businessRef(next.id).set(patch, { merge: true });
  return {
    ...next,
    estadoSuscripcion: shouldMarkInactive || shouldMarkPastDue ? erpStatus : next.estadoSuscripcion,
    enPrueba: shouldMarkInactive ? false : next.enPrueba,
    trialStatus: shouldMarkInactive ? 'expired' : next.trialStatus,
    billing: {
      ...(next.billing ?? {}),
      lifecycleStatus: resolvedLifecycle,
      updatedAt: now,
    },
    updatedAt: now,
  };
}

export function isTrialActiveForBilling(business: BusinessRecord): boolean {
  return resolveTrialState(business).isTrialBillingActive;
}
